{
  "name": "opencode-goal-lite",
  "version": "0.1.1",
  "description": "Un único Goal visual y seguro para OpenCode.",
  "type": "module",
  "main": "./src/server.js",
  "types": "./index.d.ts",
  "exports": {
    ".": {
      "types": "./index.d.ts",
      "import": "./src/server.js",
      "default": "./src/server.js"
    },
    "./server": {
      "types": "./server.d.ts",
      "import": "./src/server.js",
      "default": "./src/server.js"
    },
    "./tui": {
      "types": "./tui.d.ts",
      "import": "./src/tui.js",
      "default": "./src/tui.js"
    }
  },
  "files": [
    "src",
    "index.d.ts",
    "server.d.ts",
    "tui.d.ts",
    "README.md",
    "CHANGELOG.md",
    "CONTRIBUTING.md",
    "SECURITY.md",
    "LICENSE",
    "docs"
  ],
  "scripts": {
    "test": "node --test test/*.test.js",
    "test:coverage": "node --test --experimental-test-coverage test/*.test.js",
    "type:check": "tsc -p test/types/tsconfig.json --noEmit",
    "check": "node --check src/server.js && node --check src/tui.js && npm test && npm run type:check",
    "smoke:packed": "node scripts/packed-contract.mjs",
    "smoke:opencode-install": "node scripts/opencode-install-contract.mjs",
    "verify": "npm run check && npm run smoke:packed && npm run smoke:opencode-install && npm run pack:check",
    "pack:check": "npm pack --dry-run",
    "release:check": "npm run verify && npm run test:coverage && npm audit --omit=dev --audit-level=high"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "goal"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "1.17.18"
  },
  "devDependencies": {
    "typescript": "5.9.3"
  },
  "license": "MIT",
  "engines": {
    "node": ">=18",
    "opencode": ">=1.17.18 <2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Pablohorch/opencode-goal-lite.git"
  },
